#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Amalgamate PCSX2's Metal shaders into one C++ string literal include.

The Command Line Tools ship without the offline `metal` compiler, so instead of building
.metallib files we embed the shader source and compile it with
-[MTLDevice newLibraryWithSource:] at runtime (third_party/patches/pcsx2/0001-*.patch).

newLibraryWithSource cannot resolve quoted #includes, so this script inlines them
(honouring `#pragma once`). Each top-level .metal file is a separate translation unit
upstream, so macros a file defines (including via its private includes such as fxaa.fx)
are #undef'd at the end of that file to keep them from leaking into the next one.

usage: amalgamate_metal.py <output.inc> <file.metal>...
"""
import os
import re
import sys

INCLUDE_RE = re.compile(r'^\s*#\s*include\s+"([^"]+)"')
PRAGMA_ONCE_RE = re.compile(r'^\s*#\s*pragma\s+once\b')
DEFINE_RE = re.compile(r'^\s*#\s*define\s+([A-Za-z_][A-Za-z0-9_]*)')


def expand(path, seen_once, defines, out, shared):
    path = os.path.normpath(path)
    with open(path, encoding="utf-8") as f:
        lines = f.read().splitlines()
    if any(PRAGMA_ONCE_RE.match(l) for l in lines):
        if path in seen_once:
            return
        seen_once.add(path)
        shared = True  # macros in pragma-once headers are meant to be shared
    out.append(f"// ---- {os.path.basename(path)} ----")
    for line in lines:
        if PRAGMA_ONCE_RE.match(line):
            continue
        m = INCLUDE_RE.match(line)
        if m:
            expand(os.path.join(os.path.dirname(path), m.group(1)), seen_once, defines, out, shared)
            continue
        d = DEFINE_RE.match(line)
        if d and not shared:
            defines.append(d.group(1))
        out.append(line)


def main():
    if len(sys.argv) < 3:
        sys.exit(__doc__)
    output, inputs = sys.argv[1], sys.argv[2:]
    seen_once = set()
    out = []
    for src in inputs:
        defines = []
        expand(src, seen_once, defines, out, False)
        for name in dict.fromkeys(defines):
            out.append(f"#undef {name}")
    text = "\n".join(out) + "\n"
    # Raw string literals are limited only by the compiler; split into chunks well below
    # clang's practical limits and concatenate.
    delim = "VC_MTL"
    assert f"){delim}\"" not in text
    chunks = [text[i:i + 60000] for i in range(0, len(text), 60000)]
    body = "\n".join(f'R"{delim}({c}){delim}"' for c in chunks)
    tmp = output + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write("// Generated by third_party/scripts/amalgamate_metal.py - do not edit.\n")
        f.write(body)
        f.write("\n")
    os.replace(tmp, output)


if __name__ == "__main__":
    main()
